//! 🧳️ Explicit fixture semantics produce original typed operations from admitted field fragments.
use super::*;
use semio_framework_os_spr::{RetainedMutation,RetainedMutationPreparation,RetainedMutationAdvance,RetainedMutationDecision,RetainedMutationCloseContext,RetainedFieldPreparation};
use semio_framework_value::{RetirementDemand,retained_clone::{RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedCloneClose}};
use semio_framework_value_factory::vector::FactoryVectorRetirement;
use std::mem::{ManuallyDrop,size_of};
#[path="🔺️apply/🦀️.rs"] mod apply;
fn demand(copy_bytes:usize,capacity_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,capacity_bytes,depth:1,..Default::default()}}
fn fits(d:RetirementDemand,g:RetainedCloneGrant)->bool{semio_framework_os_spr::retained_mutation_demand_fits(d,g)}
fn progress(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}}
fn add(mut p:RetainedCloneProgress,n:usize)->RetainedCloneProgress{if p!=Default::default(){p.copied_bytes+=n;}p}
fn child(g:RetainedCloneGrant,n:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-n,..g}}
pub(crate) struct Preparation{
 fields:[RetainedFieldPreparation<String>;5],
 strings:ManuallyDrop<[Option<String>;5]>,
 decided:ManuallyDrop<Option<Diff>>,
 messages:ManuallyDrop<Option<Vec<semio_framework_os_spr::MutationMessage>>>,
 inverse:ManuallyDrop<Option<Vec<DocumentMutation>>>,
 inverse_close:Option<FactoryVectorRetirement<DocumentMutation>>,
 ledger:Option<semio_framework_os_spr::MutationMessageLedgerRetirement>,
 retirement:RetainedCloneClose,
 phase:u8,field:usize,count:usize,index:usize,inverse_phase:u8,inverse_field:usize,closing:bool,
}
impl RetainedMutation<Document> for DocumentMutation{type Preparation=Preparation;}
impl Preparation{
 fn source<'a>(&self,m:RetainedCloneRef<'a,DocumentMutation>,p:RetainedCloneRef<'a,Document>,field:usize)->Option<RetainedCloneRef<'a,String>>{
  match (m.get(),field){
   (DocumentMutation::Insert{..},0)=>Some(m.project(0,|m|match m{DocumentMutation::Insert{id,..}=>id,_=>unreachable!()})),
   (DocumentMutation::Insert{..}|DocumentMutation::SetText{..},1)=>Some(m.project(1,|m|match m{DocumentMutation::Insert{text,..}|DocumentMutation::SetText{text,..}=>text,_=>unreachable!()})),
   (DocumentMutation::Diagnostic{..},2)=>Some(m.project(2,|m|match m{DocumentMutation::Diagnostic{code,..}=>code,_=>unreachable!()})),
   (DocumentMutation::Diagnostic{..},3)=>Some(m.project(3,|m|match m{DocumentMutation::Diagnostic{message,..}=>message,_=>unreachable!()})),
   (DocumentMutation::Diagnostic{..},4)=>Some(p.project(4,|p|node_id(p,0))),_=>None,
  }
 }
 fn inverse_source<'a>(&self,m:RetainedCloneRef<'a,DocumentMutation>,p:RetainedCloneRef<'a,Document>,field:usize)->Option<RetainedCloneRef<'a,String>>{
  let(index,with_id)=match m.get(){DocumentMutation::Insert{..}=>return None,DocumentMutation::Remove{index}=>(*index,true),DocumentMutation::SetText{index,..}=>(*index,false),DocumentMutation::RemoveRange{start,..}=>(start+self.index,true),DocumentMutation::Diagnostic{..}=>(0,false)};
  if field==0&&with_id{Some(p.project(index*2,move|p|node_id(p,index)))}else if field==1{Some(p.project(index*2+1,move|p|node_text(p,index)))}else{None}
 }
 fn field_demand(&self,source:Option<RetainedCloneRef<'_,String>>,i:usize,body:usize)->Result<RetirementDemand,ValueError>{let fixed=size_of::<usize>()+size_of::<Option<String>>();if let Some(source)=source{let mut d=if self.fields[i].value().is_some(){self.fields[i].exchange_demand()?}else{self.fields[i].demand(source,body.saturating_sub(fixed))?};d.copy_bytes+=fixed;Ok(d)}else{Ok(demand(fixed,0))}}
 fn field_step(&mut self,source:Option<RetainedCloneRef<'_,String>>,i:usize,body:usize,g:RetainedCloneGrant)->Result<(bool,RetainedCloneProgress),ValueError>{let fixed=size_of::<usize>()+size_of::<Option<String>>();if let Some(source)=source{if self.fields[i].value().is_some(){let(value,p)=self.fields[i].take(child(g,fixed))?;let ready=value.is_some();self.strings[i]=value;Ok((ready,add(p,fixed)))}else{let s=self.fields[i].advance(source,body.saturating_sub(fixed),child(g,fixed))?;Ok((false,add(s.progress(),fixed)))}}else{Ok((true,progress(demand(fixed,0))))}}
}
impl RetainedMutationPreparation<Document,DocumentMutation> for Preparation{
 fn new()->Self{Self{fields:std::array::from_fn(|_|Default::default()),strings:ManuallyDrop::new(std::array::from_fn(|_|None)),decided:ManuallyDrop::new(None),messages:ManuallyDrop::new(None),inverse:ManuallyDrop::new(None),inverse_close:None,ledger:None,retirement:Default::default(),phase:0,field:0,count:0,index:0,inverse_phase:0,inverse_field:0,closing:false}}
 fn decision_demand(&self,m:RetainedCloneRef<'_,DocumentMutation>,p:RetainedCloneRef<'_,Document>,body:usize)->Result<RetirementDemand,ValueError>{Ok(match self.phase{0=>demand(4*size_of::<usize>()+size_of::<u8>(),0),1=>return self.field_demand(self.source(m,p,self.field),self.field,body),2=>demand(size_of::<Diff>()+size_of::<Vec<semio_framework_os_spr::MutationMessage>>(),self.count.checked_mul(size_of::<Op>()).ok_or_else(out_of_range)?),3=>{let diagnostic=matches!(m.get(),DocumentMutation::Diagnostic{..});demand(size_of::<Op>()*2+size_of::<semio_framework_os_spr::MutationMessage>()+5*size_of::<Option<String>>()+size_of::<usize>()+32,if diagnostic{size_of::<semio_framework_os_spr::MutationMessage>()+size_of::<String>()+"diagnostic applied".len()}else{0})},_=>demand(size_of::<u8>(),0)})}
 fn decide(&mut self,m:RetainedCloneRef<'_,DocumentMutation>,p:RetainedCloneRef<'_,Document>,body:usize,g:RetainedCloneGrant)->Result<RetainedMutationAdvance,ValueError>{let d=self.decision_demand(m,p,body)?;if !fits(d,g){return Ok(RetainedMutationAdvance::Progress(Default::default()));}let mut receipt=progress(d);match self.phase{
  0=>{DIFF_CALLS.set(DIFF_CALLS.get()+1);self.count=match m.get(){DocumentMutation::RemoveRange{count,..}=>*count,_=>1};self.phase=1;},
  1=>{let(done,p)=self.field_step(self.source(m,p,self.field),self.field,body,g)?;receipt=p;if done{self.field+=1;if self.field==5{self.phase=2;}}},
  2=>{*self.decided=Some(Diff{ops:Vec::with_capacity(self.count)});*self.messages=Some(Vec::new());receipt.retained_capacity_bytes=self.decided.as_ref().unwrap().ops.capacity()*size_of::<Op>();self.phase=3;},
  3=>{if self.index<self.count{let op=match m.get(){DocumentMutation::Insert{index,..}=>Op::Insert{index:*index,id:self.strings[0].take().unwrap(),text:self.strings[1].take().unwrap()},DocumentMutation::Remove{index}=>Op::Remove{index:*index},DocumentMutation::SetText{index,..}=>Op::SetText{index:*index,text:self.strings[1].take().unwrap()},DocumentMutation::RemoveRange{start,..}=>Op::Remove{index:*start},DocumentMutation::Diagnostic{level,..}=>{let mut row=match level.as_str(){"info"=>semio_framework_os_spr::MutationMessage::info(self.strings[2].take().unwrap(),self.strings[3].take().unwrap()),"warning"=>semio_framework_os_spr::MutationMessage::warning(self.strings[2].take().unwrap(),self.strings[3].take().unwrap()),"error"=>semio_framework_os_spr::MutationMessage::error(self.strings[2].take().unwrap(),self.strings[3].take().unwrap()),"fatal"=>semio_framework_os_spr::MutationMessage::fatal(self.strings[2].take().unwrap(),self.strings[3].take().unwrap()),_=>return Err(out_of_range())};row.target=Vec::with_capacity(1);row.target.push(self.strings[4].take().unwrap());*self.messages=Some(Vec::with_capacity(1));self.messages.as_mut().unwrap().push(row);let text=String::from("diagnostic applied");receipt.retained_capacity_bytes=self.messages.as_ref().unwrap().capacity()*size_of::<semio_framework_os_spr::MutationMessage>()+self.messages.as_ref().unwrap()[0].target.capacity()*size_of::<String>()+text.capacity();Op::SetText{index:0,text}}};self.decided.as_mut().unwrap().ops.push(op);self.index+=1;}if self.index==self.count{self.phase=4;}},_=>return Ok(RetainedMutationAdvance::Ready(Default::default())),}
  if receipt.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"fixture retained decision backing exceeded its quote").with_retained_progress(receipt));}Ok(if self.phase==4{RetainedMutationAdvance::Ready(receipt)}else{RetainedMutationAdvance::Progress(receipt)})
 }
 fn take_decision(&mut self)->RetainedMutationDecision<Diff>{assert_eq!(self.phase,4);self.phase=5;RetainedMutationDecision::Admitted(self.decided.take().unwrap(),self.messages.take().unwrap())}
 fn inverse_demand(&self,m:RetainedCloneRef<'_,DocumentMutation>,p:RetainedCloneRef<'_,Document>,_:RetainedCloneRef<'_,Diff>,body:usize)->Result<RetirementDemand,ValueError>{Ok(match self.inverse_phase{0=>demand(size_of::<Vec<DocumentMutation>>()+4*size_of::<usize>(),match m.get(){DocumentMutation::RemoveRange{count,..}=>*count,_=>1}.checked_mul(size_of::<DocumentMutation>()).ok_or_else(out_of_range)?),1=>{if !self.fields[self.inverse_field].terminal_is_empty(){return self.fields[self.inverse_field].close_demand(body);}demand(size_of::<RetainedFieldPreparation<String>>()+size_of::<usize>(),0)},2=>return self.field_demand(self.inverse_source(m,p,self.inverse_field),self.inverse_field,body),3=>demand(size_of::<DocumentMutation>()*2+2*size_of::<Option<String>>()+size_of::<usize>(),0),_=>demand(size_of::<u8>(),0)})}
 fn inverse(&mut self,m:RetainedCloneRef<'_,DocumentMutation>,p:RetainedCloneRef<'_,Document>,dref:RetainedCloneRef<'_,Diff>,body:usize,g:RetainedCloneGrant)->Result<RetainedMutationAdvance,ValueError>{let d=self.inverse_demand(m,p,dref,body)?;if !fits(d,g){return Ok(RetainedMutationAdvance::Progress(Default::default()));}let mut receipt=progress(d);match self.inverse_phase{
  0=>{INVERSE_CALLS.set(INVERSE_CALLS.get()+1);self.count=match m.get(){DocumentMutation::RemoveRange{count,..}=>*count,_=>1};*self.inverse=Some(Vec::with_capacity(self.count));receipt.retained_capacity_bytes=self.inverse.as_ref().unwrap().capacity()*size_of::<DocumentMutation>();self.index=0;self.inverse_field=0;self.fields[0].begin_close();self.inverse_phase=if self.count==0{4}else{1};},
  1=>{if !self.fields[self.inverse_field].terminal_is_empty(){receipt=self.fields[self.inverse_field].close_step(g)?.progress();}else{self.fields[self.inverse_field]=Default::default();self.inverse_phase=2;}},
  2=>{let(done,p)=self.field_step(self.inverse_source(m,p,self.inverse_field),self.inverse_field,body,g)?;receipt=p;if done{if self.inverse_field==0{self.inverse_field=1;self.fields[1].begin_close();self.inverse_phase=1;}else{self.inverse_phase=3;}}},
  3=>{let row=match m.get(){DocumentMutation::Insert{index,..}=>DocumentMutation::Remove{index:*index},DocumentMutation::Remove{index}=>DocumentMutation::Insert{index:*index,id:self.strings[0].take().unwrap(),text:self.strings[1].take().unwrap()},DocumentMutation::SetText{index,..}=>DocumentMutation::SetText{index:*index,text:self.strings[1].take().unwrap()},DocumentMutation::RemoveRange{start,..}=>DocumentMutation::Insert{index:start+self.index,id:self.strings[0].take().unwrap(),text:self.strings[1].take().unwrap()},DocumentMutation::Diagnostic{..}=>DocumentMutation::SetText{index:0,text:self.strings[1].take().unwrap()}};self.inverse.as_mut().unwrap().push(row);self.index+=1;if self.index==self.count{self.inverse_phase=4;}else{self.inverse_field=0;self.fields[0].begin_close();self.inverse_phase=1;}},_=>return Ok(RetainedMutationAdvance::Ready(Default::default())),}
  if receipt.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"fixture inverse backing exceeded quote").with_retained_progress(receipt));}Ok(if self.inverse_phase==4{RetainedMutationAdvance::Ready(receipt)}else{RetainedMutationAdvance::Progress(receipt)})
 }
 fn take_inverse(&mut self)->Vec<DocumentMutation>{assert_eq!(self.inverse_phase,4);self.inverse_phase=5;self.inverse.take().unwrap()}
 fn begin_close(&mut self){self.closing=true;for f in &mut self.fields{f.begin_close();}}
 fn close_demand(&self,c:RetainedMutationCloseContext<'_,DocumentMutation>,body:usize)->Result<RetirementDemand,ValueError>{for f in &self.fields{if !f.terminal_is_empty(){return f.close_demand(body);}}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<Diff>(false,&None,body);}if self.decided.is_some(){return self.retirement.next_owner_demands::<Diff>(true,&None,body);}if self.strings.iter().any(Option::is_some){return self.retirement.next_owner_demands::<String>(true,&None,body);}if let Some(o)=self.inverse_close.as_ref(){return o.demands(c.mutations,body);}if self.inverse.is_some(){return Ok(FactoryVectorRetirement::<DocumentMutation>::constructor_demand());}if self.messages.is_some(){return Ok(demand(size_of::<semio_framework_os_spr::MutationMessageLedgerRetirement>(),0));}if let Some(o)=self.ledger.as_ref(){return Ok(RetirementDemand{copy_bytes:o.next_copy_byte_demand(),capacity_bytes:o.next_capacity_byte_demand(body)?,release_bytes:o.next_release_byte_demand()?,depth:o.next_depth_demand()?});}Ok(Default::default())}
 fn close_step(&mut self,c:RetainedMutationCloseContext<'_,DocumentMutation>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{assert!(self.closing);let d=self.close_demand(c,g.maximum_copy_bytes)?;if !fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}for f in &mut self.fields{if !f.terminal_is_empty(){return f.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()));}}if !self.retirement.is_empty(){return self.retirement.step_granted(g).map(|s|RetainedCloneStep::Progress(s.progress()));}if let Some(s)=self.retirement.begin_granted(&mut self.decided,g)?{return Ok(RetainedCloneStep::Progress(s.progress()));}for s in self.strings.iter_mut(){if let Some(p)=self.retirement.begin_granted(s,g)?{return Ok(RetainedCloneStep::Progress(p.progress()));}}if let Some(o)=self.inverse_close.as_mut(){let s=o.close_step(c.mutations,g)?;if o.terminal_is_empty(){self.inverse_close=None;}return Ok(RetainedCloneStep::Progress(s.progress()));}if let Some(rows)=self.inverse.take(){return match FactoryVectorRetirement::admit(rows,g){Ok((o,p))=>{self.inverse_close=Some(o);Ok(RetainedCloneStep::Progress(p))},Err((e,rows))=>{*self.inverse=Some(rows);Err(e)}};}if let Some(rows)=self.messages.take(){self.ledger=Some(semio_framework_os_spr::MutationMessageLedgerRetirement::new(String::new(),rows));return Ok(RetainedCloneStep::Progress(progress(d)));}if let Some(o)=self.ledger.as_mut(){let s=o.close_step(g)?;if o.terminal_is_empty(){self.ledger=None;}return Ok(RetainedCloneStep::Progress(s.progress()));}Ok(RetainedCloneStep::Complete(Default::default()))}
 fn terminal_is_empty(&self)->bool{self.fields.iter().all(|f|f.terminal_is_empty())&&self.strings.iter().all(Option::is_none)&&self.decided.is_none()&&self.messages.is_none()&&self.inverse.is_none()&&self.inverse_close.is_none()&&self.ledger.is_none()&&self.retirement.is_empty()}
}
impl Drop for Preparation{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty);if empty{unsafe{ManuallyDrop::drop(&mut self.strings);ManuallyDrop::drop(&mut self.decided);ManuallyDrop::drop(&mut self.messages);ManuallyDrop::drop(&mut self.inverse);}}}}
